<?php
$cutoff=$_GET['cutoff']??date('Y-m-d');$scope=balanceScope($u,$cutoff);
$cutoffTime=$cutoff.' 23:59:59';$snapshots=[];
foreach(rows('SELECT s.*,d.name department FROM balance_snapshots s JOIN departments d ON d.id=s.department_id WHERE s.created_at<=? AND NOT EXISTS(SELECT 1 FROM balance_snapshots newer WHERE newer.user_id=s.user_id AND newer.created_at<=? AND (newer.created_at>s.created_at OR (newer.created_at=s.created_at AND newer.id>s.id))) ORDER BY s.user_id',[$cutoffTime,$cutoffTime]) as $snapshot) {
    if ((int)$snapshot['user_id']===(int)$u['id'] || $scope['all'] || in_array((int)$snapshot['department_id'],$scope['departments'],true)) $snapshots[]=$snapshot;
}
?>
<p class="page-intro">Consulta los saldos registrados a una fecha de corte. Los jefes y suplentes consultan únicamente las dependencias y fechas comprendidas en sus designaciones. Para una designación finalizada, selecciona una fecha de ese periodo.</p>
<section class="panel form-panel"><form method="get" class="filter-form"><input type="hidden" name="page" value="balances"><label>Fecha de corte<input type="date" name="cutoff" value="<?=e($cutoff)?>" max="<?=date('Y-m-d')?>" required></label><button class="button secondary">Consultar saldos</button></form><p class="fine">El historial de saldos comienza con la actualización de esta versión. No se reconstruyen saldos anteriores sin evidencia. Los tiempos aprobados incluyen el disfrute autorizado que todavía no haya ocurrido.</p></section>
<?php foreach($snapshots as $snapshot): $balance=json_decode($snapshot['data'],true,512,JSON_THROW_ON_ERROR); ?>
<section class="panel"><div class="panel-header"><div><h2><?=e($balance['name'])?></h2><p><?=e($snapshot['department'])?> · Último movimiento hasta el corte: <?=e($snapshot['created_at'])?></p></div></div>
<div class="form-panel"><h3>Ordinario-Remunerado disponible por semestre</h3><?php foreach($balance['quotas'] as $semester=>$available): ?><p><?=e($semester)?>: <strong><?=e(hours($available))?></strong> de 25 h 30 min</p><?php endforeach; ?></div>
<div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Reservado / en trámite</th><th>Aprobado o disfrutado</th><th>Beneficio anual</th></tr></thead><tbody><?php foreach($balance['types'] as $type): ?><tr><td><?=e($type['name'])?><small><?=e(familyLabel($type['family']))?></small></td><td><?=e(hours($type['reserved']))?></td><td><?=e(hours($type['used']))?></td><td><?=e(implode(', ',$type['birthday_years']))?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="form-panel"><h3>Compensatorios por acto administrativo</h3><?php if(!$balance['acts']): ?><p>Sin actos aprobados a la fecha del registro.</p><?php endif; foreach($balance['acts'] as $act): ?><p><strong><?=e($act['number'])?></strong> · Otorgado: <?=e(hours($act['granted']))?> · Sin asignar: <?=e(hours($act['available']))?> · Vence: <?=e($act['expires_on'])?> <?=$act['expires_on']<$cutoff?'(vencido al corte)':''?></p><?php endforeach; ?></div></section>
<?php endforeach; if(!$snapshots): ?><section class="panel form-panel"><p>No hay registros de saldos disponibles para tu alcance y la fecha seleccionada.</p></section><?php endif; ?>
